  { json: { id: 'demo-viaje-oaxaca', titulo: 'Escapada a Oaxaca: 3 noches con desayuno', categoria: 'viajes', origen: 'Ciudad de México', destino: 'Oaxaca de Juárez', precio: 4500, moneda: 'MXN', fecha_inicio: '2026-11-01', fecha_fin: '2026-11-30', detalles: 'Hotel boutique en el centro histórico. Cancelación gratuita hasta 48 h antes.', url_reserva: 'https://ejemplo.com/ofertas/oaxaca-3-noches' } },
  { json: { id: 'demo-empleo-data-engineer', titulo: 'Data Engineer Sr. (remoto, LATAM)', categoria: 'empleos', origen: 'Remoto', destino: 'LATAM', precio: 0, fecha_inicio: null, fecha_fin: '2026-10-31', detalles: 'Python, SQL, Airflow, dbt. Contrato indefinido, horario flexible.', url_reserva: 'https://ejemplo.com/empleos/data-engineer' } },
  { json: { id: 'demo-servicio-auditoria-n8n', titulo: 'Auditoría de automatizaciones n8n para tu negocio', categoria: 'servicios', origen: 'Online', destino: 'México', precio: 1990, moneda: 'MXN', fecha_inicio: '2026-09-20', fecha_fin: '2026-12-31', detalles: 'Sesión de 90 minutos + reporte con oportunidades de automatización priorizadas.', url_reserva: 'https://luisdavidmag.com/contact' } }
];

const CATEGORIES = ['viajes', 'vuelos', 'empleos', 'servicios'];
const nowIso = new Date().toISOString();
const toDate = v => { if (!v) return null; const d = new Date(v); return isNaN(d) ? null : d.toISOString().slice(0, 10); };

const out = [];
for (const item of $input.all()) {
  const r = item.json;
  const id = String(r.id ?? '').trim();
  const titulo = String(r.titulo ?? '').trim().slice(0, 160);
  const categoria = String(r.categoria ?? '').trim().toLowerCase();
  const url_reserva = String(r.url_reserva ?? '').trim();
  if (!id || !titulo || !CATEGORIES.includes(categoria) || !/^https?:\/\//i.test(url_reserva)) continue;

  const precio = typeof r.precio === 'number' ? r.precio : Number(String(r.precio ?? '0').replace(/[^0-9.]/g, '')) || 0;

  out.push({ json: {
    id, titulo, categoria,
    origen: String(r.origen ?? '').trim(),
    destino: String(r.destino ?? '').trim(),
    precio: Math.max(0, precio),
    moneda: (String(r.moneda ?? 'MXN').trim().toUpperCase().slice(0, 3)) || 'MXN',
    fecha_inicio: toDate(r.fecha_inicio),
    fecha_fin: toDate(r.fecha_fin),
    detalles: String(r.detalles ?? '').trim().slice(0, 2000),
    url_reserva,
    activo: true,
    updated_at: nowIso
  } });
}
return out;
